#!/usr/bin/env bash
# Question 1: Pod ${Q1_CLAIM}-app never starts. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

if ! kubectl -n local-path-storage get deployment local-path-provisioner >/dev/null 2>&1; then
  [[ -f /opt/cka/addons/local-path-storage.yaml ]] || { echo "these lab images have no local-path provisioner: run ./cka images extras (or rebuild the images)" >&2; exit 1; }
  kubectl apply -f /opt/cka/addons/local-path-storage.yaml >/dev/null
fi
kubectl -n local-path-storage rollout status deployment/local-path-provisioner --timeout=180s >/dev/null
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete pod --all --wait=true >/dev/null 2>&1 || true
kubectl -n "${Q1_NS}" delete pvc --all --wait=true >/dev/null 2>&1 || true
kubectl delete storageclass "${Q1_CLAIM}-local" --ignore-not-found >/dev/null
# Faults append assignments here (provisioner=..., class=...), read back after the break: a file,
# because a layered question runs each fault in its own subshell.
: > "/var/tmp/cka-q1.prov"

case "${Q1_FAULT}" in
  provisioner-typo)
    echo 'provisioner=rancher.io/localpath' >> "/var/tmp/cka-q1.prov"
    ;;
  no-class)
    echo 'class=no' >> "/var/tmp/cka-q1.prov"
    ;;
  rwop-taken)
    echo 'mode=ReadWriteOncePod' >> "/var/tmp/cka-q1.prov"
    kubectl apply -f - <<< '{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q1_CLAIM}"'","namespace":"'"${Q1_NS}"'"},"spec":{"storageClassName":"'"${Q1_CLAIM}"'-local","accessModes":["ReadWriteOncePod"],"resources":{"requests":{"storage":"500Mi"}}}}' >/dev/null 2>&1 || true
    kubectl apply -f - <<< '{"apiVersion":"storage.k8s.io/v1","kind":"StorageClass","metadata":{"name":"'"${Q1_CLAIM}-local"'"},"provisioner":"rancher.io/local-path","volumeBindingMode":"WaitForFirstConsumer","reclaimPolicy":"Delete"}' >/dev/null
    kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q1_CLAIM}-backup"'","namespace":"'"${Q1_NS}"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}]}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"${Q1_CLAIM}"'"}}]}}'
    kubectl -n "${Q1_NS}" wait --for=condition=Ready "pod/${Q1_CLAIM}-backup" --timeout=180s
    ;;
  hostpath-missing)
    echo 'hostdir=/var/log/${Q1_CLAIM}-app' >> "/var/tmp/cka-q1.prov"
    ;;
  claim-elsewhere)
    kubectl create namespace "${Q1_NS}-shared" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}-shared" >/dev/null
    timeout 60 bash -c "until kubectl -n '${Q1_NS}-shared' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
    kubectl apply -f - <<< '{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q1_CLAIM}"'","namespace":"'"${Q1_NS}-shared"'"},"spec":{"storageClassName":"'"${Q1_CLAIM}"'-local","accessModes":["ReadWriteOnce"],"resources":{"requests":{"storage":"500Mi"}}}}' >/dev/null
    echo "skipclaim=yes" >> "/var/tmp/cka-q1.prov"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

provisioner=rancher.io/local-path class=yes mode=ReadWriteOnce hostdir= skipclaim=
. "/var/tmp/cka-q1.prov"
kubectl apply -f - <<< '{"apiVersion":"storage.k8s.io/v1","kind":"StorageClass","metadata":{"name":"'"${Q1_CLAIM}-local"'"},"provisioner":"'"$provisioner"'","volumeBindingMode":"WaitForFirstConsumer","reclaimPolicy":"Delete"}' >/dev/null
extra=''
[[ "$class" == yes ]] && extra='"storageClassName":"'"${Q1_CLAIM}"'-local",'
[[ "$skipclaim" == yes ]] || kubectl apply -f - <<< '{"apiVersion":"v1","kind":"PersistentVolumeClaim","metadata":{"name":"'"${Q1_CLAIM}"'","namespace":"'"${Q1_NS}"'"},"spec":{'"$extra"'"accessModes":["'"$mode"'"],"resources":{"requests":{"storage":"500Mi"}}}}' >/dev/null
vol='' mnt=''
if [[ -n "$hostdir" ]]; then
  vol=',{"name":"logs","hostPath":{"path":"'"$hostdir"'","type":"Directory"}}'
  mnt=',{"name":"logs","mountPath":"/logs"}'
fi
kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q1_CLAIM}-app"'","namespace":"'"${Q1_NS}"'"},"spec":{"containers":[{"name":"app","image":"busybox:1.36","command":["sleep","1d"],"volumeMounts":[{"name":"data","mountPath":"/data"}'"$mnt"']}],"volumes":[{"name":"data","persistentVolumeClaim":{"claimName":"'"${Q1_CLAIM}"'"}}'"$vol"']}}' >/dev/null
sleep 20
[[ "$(kubectl -n "${Q1_NS}" get pod "${Q1_CLAIM}-app" -o jsonpath='{.status.phase}')" != Running ]] || { echo "${Q1_CLAIM}-app runs" >&2; exit 1; }
